export function TextField({ label }: { label: string }) {
  return (
    <div className="relative w-full">
      <input
        id="text-field"
        type="text"
        placeholder=" "
        className="peer w-full rounded-lg border border-stone-300 bg-white px-3.5 pb-2 pt-5 text-sm text-stone-900 outline-none transition-colors focus:border-emerald-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:focus-visible:outline-emerald-400 dark:border-stone-600 dark:bg-stone-950 dark:text-stone-100"
      />
      <label
        htmlFor="text-field"
        className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-sm text-stone-500 transition-all duration-200 ease-out peer-focus:top-3.5 peer-focus:text-xs peer-focus:text-emerald-700 peer-[:not(:placeholder-shown)]:top-3.5 peer-[:not(:placeholder-shown)]:text-xs peer-[:not(:placeholder-shown)]:text-stone-500 dark:peer-[:not(:placeholder-shown)]:text-stone-400"
      >
        {label}
      </label>
      <span className="pointer-events-none absolute inset-x-3.5 bottom-1.5 h-px origin-left scale-x-0 bg-emerald-600 transition-transform duration-300 ease-out peer-focus:scale-x-100" />
    </div>
  );
}
